func sumSeq(xs []int) int {
	t := 0
	for _, x := range xs {
		t += x
	}
	return t
}

// AI version: "one goroutine per element uses every core"
func sumGo(xs []int) int {
	var mu sync.Mutex
	var wg sync.WaitGroup
	t := 0
	for _, x := range xs {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mu.Lock()
			t += x
			mu.Unlock()
		}()
	}
	wg.Wait()
	return t
}

func compressAll(files [][]byte) [][]byte {
	out := make([][]byte, len(files))
	jobs := make(chan int)
	var wg sync.WaitGroup
	for range 200 { // goroutines are cheap
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = gzipBytes(files[i]) // pure CPU, no I/O
			}
		}()
	}
	for i := range files {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}
